//! Closed Lean applications for every actual pipeline IR pair.
use super::ir::{Comparison, Domain, Model, Predicate, Update};
use super::passes::Evidence;
use std::fmt::Write;

pub(super) struct Builder {
    out: String,
    count: usize,
}
impl Builder {
    pub(super) fn new(model: &Model) -> Self {
        let mut out = String::from(
            "-- Generated by tlx. Lean was NOT run.\n-- Closed transition-IR proof; source lowering and TLA+ emission remain trusted.\n",
        );
        out.push_str(include_str!("Rules.lean"));
        out.push_str(include_str!("PipelineCertificate.lean"));
        out.push_str("\nnamespace TlxOptimization.GeneratedPipeline\nopen TlxOptimization PipelineRule\nset_option linter.unusedVariables false\nset_option linter.unusedSimpArgs false\nset_option maxHeartbeats 0\nset_option maxRecDepth 10000\n");
        writeln!(out, "abbrev State := Fin {} → Nat", model.variables.len()).unwrap();
        emit_model(&mut out, 0, model);
        Self { out, count: 0 }
    }

    pub(super) fn append(&mut self, before: &Model, after: &Model, evidence: &Evidence, rule: &str) {
        let step = self.count;
        self.count += 1;
        let b = format!("M{step}");
        let a = format!("M{}", self.count);
        emit_model(&mut self.out, self.count, after);
        let out = &mut self.out;
        writeln!(out, "namespace Step{step}\ndef rule : String := {}", super::lean::literal(rule)).unwrap();
        context(out, before, evidence);
        writeln!(out, "theorem initial_commutes : project {b}.initial = {a}.initial := by\n  funext i").unwrap();
        indices(out, before.variables.len());
        writeln!(out, "  all_goals simp [project, {b}.initial, {a}.initial]").unwrap();
        writeln!(out, "theorem initial_valid (s : State) (hs : {b}.system.initial s) : valid s := by\n  change s = {b}.initial at hs\n  subst s\n  simp [valid, {b}.initial]").unwrap();
        writeln!(out, "theorem closed (s t : State) (hs : valid s) (hn : {b}.system.next s t) : valid t := by").unwrap();
        split_actions(out, &b, before.actions.len(), "hn");
        for i in 0..before.actions.len() {
            writeln!(out, "  · rcases h with ⟨hg, rfl⟩\n    simp_all [valid, {b}.guard{i}, {b}.update{i}] <;> omega").unwrap();
        }
        let retained: Vec<usize> = match evidence {
            Evidence::DeadActions { retained } => retained.clone(),
            Evidence::CounterSaturation { .. } | Evidence::ConstantState { .. } | Evidence::SimplifyPredicates => {
                (0..before.actions.len()).collect()
            }
        };
        for (j, &i) in retained.iter().enumerate() {
            writeln!(out, "theorem guard{j} (s : State) (hs : valid s) : {b}.guard{i} s ↔ {a}.guard{j} (project s) := by\n  simp_all [valid, {b}.guard{i}, {a}.guard{j}, project] <;> omega").unwrap();
            writeln!(
                out,
                "theorem update{j} (s : State) (hs : valid s) : project ({b}.update{i} s) = {a}.update{j} (project s) := by\n  funext i"
            )
            .unwrap();
            indices(out, before.variables.len());
            writeln!(out, "  all_goals simp_all [valid, project, {b}.update{i}, {a}.update{j}] <;> first | omega | (split <;> omega)")
                .unwrap();
        }
        writeln!(
            out,
            "theorem forward (s t : State) (hs : valid s) (hn : {b}.system.next s t) : {a}.system.next (project s) (project t) := by"
        )
        .unwrap();
        split_actions(out, &b, before.actions.len(), "hn");
        for i in 0..before.actions.len() {
            writeln!(out, "  · rcases h with ⟨hg, rfl⟩").unwrap();
            if let Some(j) = retained.iter().position(|x| *x == i) {
                writeln!(out, "    exact {}", disj_case(j, retained.len(), &format!("⟨(guard{j} s hs).mp hg, update{j} s hs⟩"))).unwrap();
            } else {
                writeln!(out, "    simp [{b}.guard{i}] at hg").unwrap();
            }
        }
        writeln!(out, "theorem backward (s y : State) (hs : valid s) (hn : {a}.system.next (project s) y) : ∃ t, {b}.system.next s t ∧ project t = y := by").unwrap();
        split_actions(out, &a, after.actions.len(), "hn");
        for (j, &i) in retained.iter().enumerate() {
            writeln!(
                out,
                "  · rcases h with ⟨hg, he⟩\n    exact ⟨{b}.update{i} s, {}, (update{j} s hs).trans he.symm⟩",
                disj_case(i, before.actions.len(), &format!("⟨(guard{j} s hs).mpr hg, rfl⟩"))
            )
            .unwrap();
        }
        writeln!(out, "theorem observe (s : State) (hs : valid s) : {b}.system.safe s ↔ {a}.system.safe (project s) := by\n  simp_all [{b}.system, {a}.system, valid, project] <;> omega").unwrap();
        writeln!(out, "def application : Application {b}.system {a}.system project where\n  valid := valid\n  initialValid := initial_valid\n  closed := closed\n  initial := by\n    intro y\n    constructor\n    · intro hy\n      exact ⟨{b}.initial, rfl, initial_commutes.trans hy.symm⟩\n    · rintro ⟨s, hs, hp⟩\n      change s = {b}.initial at hs\n      change y = {a}.initial\n      rw [← hp, hs, initial_commutes]\n  forward := forward\n  backward := backward\n  observe := observe\ntheorem certificate : Certificate (reachableSystem {b}.system) (reachableSystem {a}.system) application.project := application.certificate\nend Step{step}\n").unwrap();
    }

    pub(super) fn finish(mut self) -> String {
        let n = self.count;
        let out = &mut self.out;
        writeln!(out, "def rawBefore := M0.system\ndef rawAfter := M{n}.system\ndef before := reachableSystem rawBefore\ndef after := reachableSystem rawAfter").unwrap();
        if n == 0 {
            out.push_str("def project (s : {s // Reachable rawBefore s}) := s\ntheorem certificate : Certificate before after project := by\n  constructor\n  · intro a\n    constructor\n    · intro h; exact ⟨a, h, rfl⟩\n    · rintro ⟨s, hs, rfl⟩; exact hs\n  · intro s a\n    constructor\n    · intro h; exact ⟨a, h, rfl⟩\n    · rintro ⟨t, ht, rfl⟩; exact ht\n  · intro s; rfl\n");
        } else {
            let projected = (0..n).fold("s".to_string(), |s, i| format!("(Step{i}.application.project {s})"));
            writeln!(out, "def project (s : {{s // Reachable rawBefore s}}) := {projected}").unwrap();
            out.push_str("theorem certificate : Certificate before after project := by\n  have h0 := Step0.certificate\n");
            for i in 1..n {
                writeln!(out, "  have h{i} := compose h{} Step{i}.certificate", i - 1).unwrap();
            }
            writeln!(out, "  exact h{}", n - 1).unwrap();
        }
        out.push_str(include_str!("certify/certificate.lean"));
        self.out
    }
}

fn context(out: &mut String, before: &Model, evidence: &Evidence) {
    let mut conditions = vec![];
    for (i, v) in before.variables.iter().enumerate() {
        match v.domain {
            Domain::Natural => {}
            Domain::Constant(n) => conditions.push(format!("s {i} = {n}")),
            Domain::Interval(n) => conditions.push(format!("s {i} ≤ {n}")),
        }
    }
    if let Evidence::ConstantState { variables } = evidence {
        for &i in variables {
            conditions.push(format!("s {i} = {}", before.initial[i]));
        }
    }
    writeln!(out, "def valid (s : State) : Prop := {}", join(&conditions, "∧", "True")).unwrap();
    let projected: Vec<_> = before
        .variables
        .iter()
        .enumerate()
        .map(|(i, v)| {
            if let Evidence::CounterSaturation { caps } = evidence {
                if v.domain == Domain::Natural {
                    return format!("min (s {i}) {}", caps[i]);
                }
            }
            format!("s {i}")
        })
        .collect();
    vector(out, "project", "(s : State)", &projected);
}

fn emit_model(out: &mut String, index: usize, model: &Model) {
    writeln!(out, "namespace M{index}").unwrap();
    vector(out, "initial", "", &model.initial.iter().map(ToString::to_string).collect::<Vec<_>>());
    for (i, a) in model.actions.iter().enumerate() {
        writeln!(out, "def guard{i} (s : State) : Prop := {}", predicate(&a.guard)).unwrap();
        let updates = a
            .updates
            .iter()
            .enumerate()
            .map(|(j, u)| match u {
                Update::Keep => format!("s {j}"),
                Update::Reset => "0".into(),
                Update::Increment => format!("s {j} + 1"),
                Update::SaturatingIncrement(cap) => format!("if s {j} < {cap} then s {j} + 1 else {cap}"),
            })
            .collect::<Vec<_>>();
        vector(out, &format!("update{i}"), "(s : State)", &updates);
    }
    let next = (0..model.actions.len()).map(|i| format!("(guard{i} s ∧ t = update{i} s)")).collect::<Vec<_>>();
    let safe = model.properties.iter().map(|p| predicate(&p.predicate)).collect::<Vec<_>>();
    writeln!(
        out,
        "def system : System State where\n  initial s := s = initial\n  next s t := {}\n  safe s := {}\nend M{index}\n",
        join(&next, "∨", "False"),
        join(&safe, "∧", "True")
    )
    .unwrap();
}
fn vector(out: &mut String, name: &str, args: &str, values: &[String]) {
    writeln!(out, "def {name} {args} : State := fun i => match i.val with").unwrap();
    for (i, value) in values.iter().enumerate() {
        writeln!(out, "  | {i} => {value}").unwrap();
    }
    out.push_str("  | _ => 0\n");
}
fn indices(out: &mut String, n: usize) {
    let terms = (0..n).map(|i| format!("i = {i}")).collect::<Vec<_>>();
    writeln!(out, "  have index : {} := by omega\n  rcases index with {}", join(&terms, "∨", "False"), vec!["hi"; n].join(" | ")).unwrap();
    out.push_str("  all_goals subst i\n");
}
fn split_actions(out: &mut String, model: &str, n: usize, hypothesis: &str) {
    writeln!(out, "  simp only [{model}.system] at {hypothesis}").unwrap();
    if n == 1 {
        writeln!(out, "  have h := {hypothesis}").unwrap();
    } else if n > 1 {
        writeln!(out, "  rcases {hypothesis} with {}", vec!["h"; n].join(" | ")).unwrap();
    }
}
fn disj_case(i: usize, n: usize, term: &str) -> String {
    let mut result = if i + 1 == n { term.to_string() } else { format!("(Or.inl {term})") };
    for _ in 0..i {
        result = format!("(Or.inr {result})");
    }
    result
}
fn join(parts: &[String], op: &str, identity: &str) -> String {
    if parts.is_empty() {
        identity.into()
    } else {
        format!("({})", parts.join(&format!(" {op} ")))
    }
}
fn predicate(p: &Predicate) -> String {
    match p {
        Predicate::Bool(v) => if *v { "True" } else { "False" }.into(),
        Predicate::Compare { var, op, value } => format!(
            "(s {var} {} {value})",
            match op {
                Comparison::Eq => "=",
                Comparison::Ne => "≠",
                Comparison::Lt => "<",
                Comparison::Le => "≤",
                Comparison::Gt => ">",
                Comparison::Ge => "≥",
            }
        ),
        Predicate::Not(p) => format!("(¬ {})", predicate(p)),
        Predicate::And(ps) => join(&ps.iter().map(predicate).collect::<Vec<_>>(), "∧", "True"),
        Predicate::Or(ps) => join(&ps.iter().map(predicate).collect::<Vec<_>>(), "∨", "False"),
    }
}
